      "content": "import { expect, test } from 'bun:test';
import type { UseCase } from '@agentic-ddd/core';
import type { ClassRef } from '@agentic-ddd/decorators';
import { covers, FakeLlm, InMemoryEventBus } from '@agentic-ddd/testing';
import { OperatorRuntime } from '@agentic-ddd/runtime';
import { CreateTask } from '../application/create-task';
import { CompleteTask } from '../application/complete-task';
import { TaskCompleted, TaskCreated } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { TaskOperator } from '../operators/task.operator';

test(covers(['operator:task-operator', 'criterion:0001/tools'], 'task-operator conclui tarefa usando somente create_task e complete_task e publica eventos'), async () => {
  const repository = new InMemoryTaskRepository();
  const llm = new FakeLlm([
    {
      stopReason: 'tool_calls',
      content: [{ type: 'tool_call', id: 'c1', name: 'create_task', input: { task_id: 't1', title: 'pagar contas' } }],
    },
    {
      stopReason: 'tool_calls',
      content: [{ type: 'tool_call', id: 'c2', name: 'complete_task', input: { task_id: 't1' } }],
    },
    {
      stopReason: 'end',
      content: [{ type: 'text', text: 'Tarefa t1 criada e concluida.' }],
    },
  ]);
  const eventBus = new InMemoryEventBus();
  const runtime = new OperatorRuntime({
    llm,
    eventBus,
    root: process.cwd(),
    modules: [{ name: 'tasks', path: 'app' }],
  });
  const useCases = new Map<ClassRef, UseCase<unknown, unknown>>([
    [CreateTask, new CreateTask(repository)],
    [CompleteTask, new CompleteTask(repository)],
  ]);
  await runtime.register(
    TaskOperator,
    useCases,
  );

  const result = await runtime.run('task-operator', {
    message: 'Crie a tarefa t1 e depois marque como concluida.',
  });

  expect(result.status).toBe('completed');
  expect(result.output).toBe('Tarefa t1 criada e concluida.');
  expect(result.steps).toHaveLength(3);

  const declaredTools = llm.requests.map((request) =>
    request.tools.map((tool) => tool.name),
  );
  expect(declaredTools).toEqual([
    ['complete_task', 'create_task'],
    ['complete_task', 'create_task'],
    ['complete_task', 'create_task'],
  ]);

  const invokedTools = result.steps.flatMap((step) =>
    step.tools.map((toolStep) => toolStep.call.name),
  );
  expect(invokedTools).toEqual(['create_task', 'complete_task']);

  expect(result.events).toHaveLength(2);
  expect(result.events[0]).toBeInstanceOf(TaskCreated);
  expect(result.events[1]).toBeInstanceOf(TaskCompleted);
  expect(eventBus.events).toHaveLength(2);
  expect(eventBus.events[0]).toBeInstanceOf(TaskCreated);
  expect(eventBus.events[1]).toBeInstanceOf(TaskCompleted);

  const saved = await repository.findById('t1');
  expect(saved?.status).toBe('completed');
});
